compile.workshop:
variables {
    global:
        0: Round_Attack_Time
}

rule ("chase and condition") {
    event {
        Ongoing - Global;
    }
    conditions {
        Is Game In Progress == True;
        Global.Round_Attack_Time != 0;
    }
    actions {
        Chase Global Variable Over Time(Round_Attack_Time, 0, 30, None);
    }
}

